using namespace std;
using boost::multiprecision::cpp_int;
using ull = unsigned long long;

pair<cpp_int, cpp_int> fibonacci(ull n) {
    if (n == 0) return {0, 1};

    auto [a, b] = fibonacci(n >> 1);
    cpp_int c = a * ((b << 1) - a);
    cpp_int d = a * a + b * b;

    if (n & 1) return {d, c + d};
    return {c, d};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull n, m;
    cin >> n >> m;

    cpp_int answer = 2 * (fibonacci(n + 1).first +
