    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;
using ll = long long;

pair<cpp_int, cpp_int> fibonacci(ll n) {
    if (n == 0) return {0, 1};

    auto [a, b] = fibonacci(n / 2);
    cpp_int c = a * (2 * b - a);
    cpp_int d = a * a + b * b;

    if (n % 2 == 0) return {c, d};
    return {d, c + d};
}

void solve() {
    ll n, m;
    cin >> n >> m;

    cpp_int ans = fibonacci(n + 1).first + fibonacci(m + 1).first - 1;
    cout << ans * 2 << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

